@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class ArcaneBoreAudit {
 static final BlockPos POS=InfusionAudit.POS,BASE=POS.offset(12,-2,10),BORE=BASE.above();static int ticks;static volatile int stage;static ArcaneBore.BoreEntity bore;static final List<BlockPos> PEDS=List.of(POS.offset(-3,-2,-3),POS.offset(0,-2,-3),POS.offset(3,-2,-3),POS.offset(-3,-2,0),POS.offset(3,-2,0),POS.offset(-3,-2,3),POS.offset(0,-2,3),POS.offset(3,-2,3));
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_BORE FAIL "+s);System.out.println("TC4_BORE PASS "+s);}
 static void prepare(ServerPlayer p){p.removeAllEffects();p.setHealth(p.getMaxHealth());p.getInventory().selected=0;InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;RunicAudit.clear(p);var l=p.serverLevel();l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);for(int x=-4;x<=5;x++)for(int z=-3;z<=16;z++)for(int y=-1;y<=6;y++)l.setBlock(BASE.offset(x,y,z),y==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  l.setBlock(BASE,ArcaneBore.BASE.get().defaultBlockState().setValue(ArcaneBore.FACE,Direction.EAST),3);l.setBlock(BORE,ArcaneBore.BORE.get().defaultBlockState().setValue(ArcaneBore.FACE,Direction.SOUTH),3);bore=(ArcaneBore.BoreEntity)l.getBlockEntity(BORE);ArcaneBore.BoreEntity.tick(l,BORE,bore.getBlockState(),bore);check(!bore.gettingPower()&&!bore.validItems(),"redstone and both tools required");
  var focus=new ItemStack(FociWorld.EXCAVATION.get());var pick=new ItemStack(Items.DIAMOND_PICKAXE);bore.setItem(0,focus);bore.setItem(1,pick);check(bore.validItems(),"excavation focus and damageablepick valid");pick.setDamageValue(pick.getMaxDamage()-1);check(!bore.validItems(),"stops one durability before broken");pick.setDamageValue(0);pick.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.FORTUNE),3);pick.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.EFFICIENCY),2);bore.setChanged();check(bore.fortune==3&&bore.speed==2&&bore.area==0,"pickfortune+efficiency properties");
  check(!bore.canPlaceItem(0,pick)&&!bore.canPlaceItem(1,focus)&&bore.canPlaceItem(1,pick),"slot filters");var menu=new ArcaneBore.Menu(17,p.getInventory(),bore);p.getInventory().setItem(3,new ItemStack(Items.IRON_PICKAXE));bore.setItem(1,ItemStack.EMPTY);menu.quickMoveStack(p,32);check(bore.getItem(1).is(Items.IRON_PICKAXE)&&p.getInventory().getItem(3).isEmpty(),"actual shiftclick installs pickaxe");bore.setItem(1,pick);
  var base=(ArcaneBore.BaseEntity)l.getBlockEntity(BASE);for(var f:Direction.values())check(base.getSuctionAmount(f)==(f==Direction.EAST?0:128)&&base.isConnectable(f)&&base.canInputFrom(f)&&!base.canOutputTo(f),"base original entropy suction "+f);
  l.setBlock(BASE.below(),EssentiaDevices.JAR.get().defaultBlockState(),3);var entropyJar=(WardedJarEntity)l.getBlockEntity(BASE.below());entropyJar.state.aspect=thaumcraft.api.aspects.Aspect.ENTROPY;entropyJar.state.amount=3;entropyJar.changed();bore.speedyTime=0;ArcaneBore.BoreEntity.tick(l,BORE,bore.getBlockState(),bore);check(entropyJar.state.amount==2&&bore.speedyTime==20,"actual entropy jar gives20 acceleratedblocks");l.removeBlock(BASE.below(),false);
  var nodePos=BORE.west(3).above();l.setBlock(nodePos,TC4Modern.ENERGIZED_NODE.get().defaultBlockState(),3);var node=(EnergizedNodeEntity)l.getBlockEntity(nodePos);node.auraBase.add(thaumcraft.api.aspects.Aspect.ENTROPY,100);node.energy.visBase.add(thaumcraft.api.aspects.Aspect.ENTROPY,100);node.energy.vis.add(thaumcraft.api.aspects.Aspect.ENTROPY,100);VisNetwork.register(l,node);VisNetwork.invalidate();bore.speedyTime=0;ArcaneBore.BoreEntity.tick(l,BORE,bore.getBlockState(),bore);check(bore.speedyTime==20&&node.energy.vis.getAmount(thaumcraft.api.aspects.Aspect.ENTROPY)==0,"actual100entropyvis dividedby5 gives20 acceleratedblocks");l.removeBlock(nodePos,false);
  l.setBlock(BASE.east(),Blocks.CHEST.defaultBlockState(),3);var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(BASE.east());bore.output(new ItemStack(Items.DIAMOND,11));check(chest.getItem(0).is(Items.DIAMOND)&&chest.getItem(0).getCount()==11,"actual item output inserts chest");chest.clearContent();
  // Direct original spiral selection, slow mode and unbreakable occlusion.
  for(int x=-3;x<=3;x++)for(int y=-3;y<=3;y++)l.setBlock(BORE.offset(x,y,5),Blocks.STONE.defaultBlockState(),3);bore.speedyTime=0;bore.speed=0;bore.findNext();check(bore.toDig&&bore.count==40,"unpoweredentropy still selectsblock at4x slower");var target=bore.dig;bore.speedyTime=20;bore.mine();check(l.isEmptyBlock(target)&&pick.getDamageValue()==1&&chest.getItem(0).is(Items.COBBLESTONE),"actual mining removesstate damagespick inserts drop");chest.clearContent();
  var ore=BORE.south(5);l.setBlock(ore,Blocks.DIAMOND_ORE.defaultBlockState(),3);var silk=new ItemStack(Items.DIAMOND_PICKAXE);silk.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.SILK_TOUCH),1);bore.setItem(1,silk);bore.dig=ore;bore.mine();check(java.util.stream.IntStream.range(0,chest.getContainerSize()).anyMatch(i->chest.getItem(i).is(Items.DIAMOND_ORE)),"actual silktouch preservesore");chest.clearContent();var elemental=new ItemStack(ElementalTools.item("pickaxe"));elemental.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.FORTUNE),20);bore.setItem(1,elemental);l.setBlock(ore,Blocks.IRON_ORE.defaultBlockState(),3);bore.dig=ore;bore.mine();check(chest.getItem(0).is(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(AlchemyContent.id("iron_cluster"))),"actual nativecluster fromelementalpick");chest.clearContent();bore.setItem(1,pick);
  var repairPick=new ItemStack(ElementalTools.item("pickaxe"));repairPick.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(BasicsEnchantments.REPAIR),2);repairPick.setDamageValue(20);bore.setItem(1,repairPick);bore.repair();check(bore.repairCost.size()>0&&repairPick.getDamageValue()==20,"repair first computes originalprimalcost without freehealing");for(var a:bore.repairCost.getAspects())bore.repairVis.add(a,bore.repairCost.getAmount(a));bore.repair();check(repairPick.getDamageValue()==18&&bore.repairVis.visSize()==0,"repairII heals2 andconsumesexactbufferedvis");bore.setItem(1,pick);
  bore.speedyTime=19.75f;var saved=bore.saveWithFullMetadata(l.registryAccess());var copy=new ArcaneBore.BoreEntity(BORE,bore.getBlockState());copy.loadWithComponents(saved,l.registryAccess());check(copy.speedyTime==19&&copy.getItem(1).getDamageValue()==1&&copy.getItem(0).is(FociWorld.EXCAVATION.get()),"originalSpeedyTime short truncation and toolNBT persist");
  // Natural ticks drill the wall; visual fixture and redstone on base only.
  bore.speedyTime=200;for(int x=-3;x<=3;x++)for(int y=-3;y<=3;y++)for(int z=5;z<=10;z++)l.setBlock(BORE.offset(x,y,z),Blocks.STONE.defaultBlockState(),3);l.setBlock(BASE.west(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);check(bore.gettingPower(),"base redstone activatesmounted bore");
  craftBase(p);startInfusion(p);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.connection.teleport(BORE.getX()-4,BORE.getY()+2,BORE.getZ()-5,-30,15);stage=1;
 }
 static void craftBase(ServerPlayer p){var r=ArcaneRecipes.entries().stream().filter(e->e.key().equals("ArcaneBoreBase")).findFirst().orElseThrow();var grid=r.ingredients().stream().map(i->i.getItems()[0].copy()).toList();check(r.matches(grid,Set.of("ARCANEBORE"))&&!r.matches(grid,Set.of()),"base recipe exact research gate");var wand=WandParts.make(WandParts.CAPS.get("gold"),WandParts.RODDEFS.get("greatwood"));for(var a:thaumcraft.api.aspects.Aspect.getPrimalAspects())WandData.add(wand,a,50,true);var expected=wand.copy();WandData.consumeCrafting(expected,r.cost(),true,p);var table=new SimpleContainer(10);for(int i=0;i<9;i++)table.setItem(i,grid.get(i));table.setItem(9,wand);var menu=new ArcaneWorkbenchMenu(22,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.NULL,table);check(menu.getSlot(0).getItem().is(ArcaneBore.BASE.get().asItem()),"actual arcaneworkbench producesbase");var result=menu.getSlot(0).remove(1);menu.getSlot(0).onTake(p,result);for(int i=0;i<9;i++)check(table.getItem(i).isEmpty(),"base component consumed "+i);for(var a:thaumcraft.api.aspects.Aspect.getPrimalAspects())check(WandData.get(wand,a)==WandData.get(expected,a),"base exact discountedvis "+a.getTag());menu.removed(p);}
 static void startInfusion(ServerPlayer p){var l=p.serverLevel();var r=ElementalToolsAudit.recipe("ArcaneBore");((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).setItem(new ItemStack(r.central().get()));for(var at:TravellerBootsAudit.PEDESTALS)l.setBlock(at,Blocks.AIR.defaultBlockState(),3);for(int i=0;i<8;i++){var at=PEDS.get(i);l.setBlock(at,InfusionContent.PEDESTAL.get().defaultBlockState(),3);((InfusionContent.PedestalEntity)l.getBlockEntity(at)).setItem(r.componentStacks().get(i));}for(int x=-8;x<=8;x++)l.setBlock(POS.offset(x,-2,-4),Blocks.AIR.defaultBlockState(),3);int i=0;for(var a:r.aspects().getAspects()){var at=POS.offset(i++*2-4,-2,-4);l.setBlock(at,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(at);jar.state.aspect=a;jar.state.amount=r.aspects().getAmount(a);jar.changed();}l.getEntitiesOfClass(ItemEntity.class,new AABB(POS).inflate(30)).forEach(Entity::discard);InfusionAudit.click(p,p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow());check(InfusionAudit.matrix.logic.crafting&&InfusionAudit.matrix.logic.recipeIngredients.size()==8&&InfusionAudit.matrix.logic.recipeEssentia.visSize()==112,"actual8component112essentia infusion starts");}
 static void finish(ServerPlayer p){var l=p.serverLevel();check(!InfusionAudit.matrix.logic.crafting&&((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).item().is(ArcaneBore.BORE.get().asItem()),"natural altar producesarcane bore");for(var at:PEDS)check(((InfusionContent.PedestalEntity)l.getBlockEntity(at)).item().isEmpty(),"altar consumescomponent "+at);for(int i=0;i<5;i++)check(((WardedJarEntity)l.getBlockEntity(POS.offset(i*2-4,-2,-4))).state.amount==0,"altar exactessentia "+i);stage=3;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.boreAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;if(ticks==10&&mc.player.isDeadOrDying())mc.player.respawn();var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==160){var debris=new ArcaneBoreClient.BoreDebris(mc.level,mc.player.position(),mc.player.position().add(10,0,0),Blocks.STONE.defaultBlockState(),false);check(debris.getQuadSize(0)>=.04f&&debris.getQuadSize(0)<=.07f,"debris original world size .04 to .07");check(debris.getU1()-debris.getU0()>0,"debris cropped sprite UV");check(stage==1,"server boremechanicsprepared");check(ArcaneBoreClient.rendered>0&&ArcaneBoreClient.beamsRendered>0&&ArcaneBoreClient.particlesSpawned>0,"actual originalmodel doublebeam debris rendered");LiquidDeathAudit.shot(mc,"arcane-bore-drilling.png");}if(ticks==180)server.execute(()->{var p=server.getPlayerList().getPlayer(id);check(bore.items.get(1).getDamageValue()>1,"natural ticks mine spiralwall");p.openMenu(bore,BORE);stage=2;});if(ticks==200){check(stage==2&&mc.screen instanceof ArcaneBoreClient.Screen,"actual server opens originalbore GUI");LiquidDeathAudit.shot(mc,"arcane-bore-gui.png");mc.player.closeContainer();}if(Boolean.getBoolean("tc4modern.boreQuickAuditOnly")&&ticks>=220&&(ticks-220)%20==0){int i=(ticks-220)/20;if(i>=3){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("ARCANEBORE"),i*2);mc.setScreen(book);}if(Boolean.getBoolean("tc4modern.boreQuickAuditOnly")&&ticks>=225&&(ticks-225)%20==0)LiquidDeathAudit.shot(mc,"arcane-bore-book-"+(ticks-225)/20+".png");if(ticks==1700)server.execute(()->finish(server.getPlayerList().getPlayer(id)));if(ticks>=1720&&(ticks-1720)%20==0){check(stage==3,"altarcomplete");int i=(ticks-1720)/20;if(i>=3){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("ARCANEBORE"),i*2);mc.setScreen(book);}if(ticks>=1725&&(ticks-1725)%20==0)LiquidDeathAudit.shot(mc,"arcane-bore-book-"+(ticks-1725)/20+".png");}
}
